import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from parallelSets ----
const DIMENSIONS = [
  { key: 'segment', label: 'Segment' },
  { key: 'contract', label: 'Contract' },
  { key: 'onboarding', label: 'Onboarding' },
  { key: 'outcome', label: 'Outcome' }
] as const;

type DimensionKey = (typeof DIMENSIONS)[number]['key'];
type SubscriptionRecord = Record<DimensionKey, string> & { count: number };

/**
 * Illustrative renewal cohort of 900 subscriptions. Row order fixes the category order in
 * every column, so the first row names the first band of each dimension.
 */
const subscriptionOutcomes: SubscriptionRecord[] = [
  { segment: 'Enterprise', contract: 'Annual', onboarding: 'Guided', outcome: 'Renewed', count: 138 },
  { segment: 'Enterprise', contract: 'Annual', onboarding: 'Guided', outcome: 'Churned', count: 12 },
  { segment: 'Enterprise', contract: 'Annual', onboarding: 'Self-serve', outcome: 'Renewed', count: 24 },
  { segment: 'Enterprise', contract: 'Annual', onboarding: 'Self-serve', outcome: 'Churned', count: 6 },
  { segment: 'Enterprise', contract: 'Monthly', onboarding: 'Guided', outcome: 'Renewed', count: 9 },
  { segment: 'Enterprise', contract: 'Monthly', onboarding: 'Guided', outcome: 'Churned', count: 3 },
  { segment: 'Enterprise', contract: 'Monthly', onboarding: 'Self-serve', outcome: 'Renewed', count: 17 },
  { segment: 'Enterprise', contract: 'Monthly', onboarding: 'Self-serve', outcome: 'Churned', count: 11 },
  { segment: 'Mid-market', contract: 'Annual', onboarding: 'Guided', outcome: 'Renewed', count: 80 },
  { segment: 'Mid-market', contract: 'Annual', onboarding: 'Guided', outcome: 'Churned', count: 15 },
  { segment: 'Mid-market', contract: 'Annual', onboarding: 'Self-serve', outcome: 'Renewed', count: 51 },
  { segment: 'Mid-market', contract: 'Annual', onboarding: 'Self-serve', outcome: 'Churned', count: 19 },
  { segment: 'Mid-market', contract: 'Monthly', onboarding: 'Guided', outcome: 'Renewed', count: 24 },
  { segment: 'Mid-market', contract: 'Monthly', onboarding: 'Guided', outcome: 'Churned', count: 11 },
  { segment: 'Mid-market', contract: 'Monthly', onboarding: 'Self-serve', outcome: 'Renewed', count: 52 },
  { segment: 'Mid-market', contract: 'Monthly', onboarding: 'Self-serve', outcome: 'Churned', count: 48 },
  { segment: 'Small business', contract: 'Annual', onboarding: 'Guided', outcome: 'Renewed', count: 19 },
  { segment: 'Small business', contract: 'Annual', onboarding: 'Guided', outcome: 'Churned', count: 6 },
  { segment: 'Small business', contract: 'Annual', onboarding: 'Self-serve', outcome: 'Renewed', count: 44 },
  { segment: 'Small business', contract: 'Annual', onboarding: 'Self-serve', outcome: 'Churned', count: 26 },
  { segment: 'Small business', contract: 'Monthly', onboarding: 'Guided', outcome: 'Renewed', count: 25 },
  { segment: 'Small business', contract: 'Monthly', onboarding: 'Guided', outcome: 'Churned', count: 15 },
  { segment: 'Small business', contract: 'Monthly', onboarding: 'Self-serve', outcome: 'Renewed', count: 96 },
  { segment: 'Small business', contract: 'Monthly', onboarding: 'Self-serve', outcome: 'Churned', count: 149 }
];

/** One row per observed combination of categories, carrying how many records it covers. */
type Outcome = {
  segment: string;
  contract: string;
  onboarding: string;
  outcome: string;
  count: number;
};

/** The rows, plus the columns to draw as stages in left-to-right order. */
export type Data = {
  rows: Outcome[];
  dimensions: { key: Exclude<keyof Outcome, 'count'>; label: string }[];
};

const DEMO: Data = { rows: subscriptionOutcomes, dimensions: [...DIMENSIONS] };

const MARGIN = { top: 34, right: 10, bottom: 12, left: 10 };
const NODE_WIDTH = 5;
const NODE_PADDING = 18;
const LABEL_GAP = 8;
/** A band shorter than this cannot hold its label, so the label is dropped. */
const MIN_LABEL_HEIGHT = 13;
const PATH_SEPARATOR = ' → ';

const formatCount = d3.format(',');

type Band = { id: string; name: string; value: number; column: number; x0: number; y0: number; y1: number };
type Ribbon = { id: string; d: string; fill: string; title: string };

/** Ribbon as a filled band: curved top edge out, curved bottom edge back. */
function ribbonPath(x0: number, x1: number, sy0: number, sy1: number, ty0: number, ty1: number) {
  const xm = (x0 + x1) / 2;
  return `M${x0},${sy0}C${xm},${sy0} ${xm},${ty0} ${x1},${ty0}L${x1},${ty1}C${xm},${ty1} ${xm},${sy1} ${x0},${sy1}Z`;
}

export default function ParallelSets({ data = DEMO, width }: { data?: Data; width: number }) {
  const height = Math.round(width * 0.68);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const columns = useMemo(
    () =>
      data.dimensions.map((dim) =>
        d3.rollup(
          data.rows,
          (v) => d3.sum(v, (d) => d.count),
          (d) => d[dim.key]
        )
      ),
    [data]
  );

  const color = useMemo(
    () =>
      d3
        .scaleOrdinal<string, string>()
        .domain([...columns[0].keys()])
        .range(d3.schemeObservable10),
    [columns]
  );

  const { bands, ribbons } = useMemo(() => {
    const total = d3.sum(data.rows, (d) => d.count);
    const step = (innerWidth - NODE_WIDTH) / (data.dimensions.length - 1);
    // One value-to-pixel scale for every column, so a ribbon meets its band at both ends.
    const ky = Math.max(
      d3.min(columns, (c) => (innerHeight - (c.size - 1) * NODE_PADDING) / total) ?? 0,
      0
    );

    const laidOut: Band[] = [];
    const byId = new Map<string, Band>();
    columns.forEach((categories, column) => {
      const stackHeight = total * ky + (categories.size - 1) * NODE_PADDING;
      let y = (innerHeight - stackHeight) / 2;
      for (const [name, value] of categories) {
        const band = {
          id: `${column}|${name}`,
          name,
          value,
          column,
          x0: column * step,
          y0: y,
          y1: y + value * ky
        };
        laidOut.push(band);
        byId.set(band.id, band);
        y = band.y1 + NODE_PADDING;
      }
    });

    const outCursor = new Map(laidOut.map((b) => [b.id, b.y0]));
    const inCursor = new Map(laidOut.map((b) => [b.id, b.y0]));
    const drawn: Ribbon[] = [];

    for (let i = 1; i < data.dimensions.length; i++) {
      // Grouping by the whole prefix, not just the adjacent pair, keeps each ribbon tied to
      // the path it came from — that is what separates parallel sets from a plain sankey.
      const paths = d3.rollup(
        data.rows,
        (v) => d3.sum(v, (d) => d.count),
        (d) =>
          data.dimensions
            .slice(0, i + 1)
            .map((dim) => d[dim.key])
            .join(PATH_SEPARATOR)
      );
      for (const [key, value] of paths) {
        const names = key.split(PATH_SEPARATOR);
        const source = byId.get(`${i - 1}|${names[i - 1]}`);
        const target = byId.get(`${i}|${names[i]}`);
        if (!source || !target) continue;
        const sy0 = outCursor.get(source.id) ?? 0;
        const ty0 = inCursor.get(target.id) ?? 0;
        const thickness = value * ky;
        outCursor.set(source.id, sy0 + thickness);
        inCursor.set(target.id, ty0 + thickness);
        drawn.push({
          id: `${i}:${key}`,
          d: ribbonPath(source.x0 + NODE_WIDTH, target.x0, sy0, sy0 + thickness, ty0, ty0 + thickness),
          fill: color(names[0]),
          title: `${key}\n${formatCount(value)} subscriptions`
        });
      }
    }

    return { bands: laidOut, ribbons: drawn };
  }, [data, columns, color, innerWidth, innerHeight]);

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Parallel sets of 900 subscriptions flowing through segment, contract, onboarding and renewal outcome"
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        {ribbons.map((ribbon) => (
          <path key={ribbon.id} d={ribbon.d} fill={ribbon.fill} fillOpacity={0.45}>
            <title>{ribbon.title}</title>
          </path>
        ))}
        {bands.map((band) => (
          <rect
            key={band.id}
            x={band.x0}
            y={band.y0}
            width={NODE_WIDTH}
            height={Math.max(band.y1 - band.y0, 0)}
            fill={band.column === 0 ? color(band.name) : 'var(--text)'}
            fillOpacity={band.column === 0 ? 1 : 0.75}
          >
            <title>{`${band.name}\n${formatCount(band.value)} subscriptions`}</title>
          </rect>
        ))}
        {bands
          .filter((band) => band.y1 - band.y0 >= MIN_LABEL_HEIGHT)
          .map((band) => {
            const onRight = band.column < data.dimensions.length / 2;
            return (
              <text
                key={band.id}
                x={onRight ? band.x0 + NODE_WIDTH + LABEL_GAP : band.x0 - LABEL_GAP}
                y={(band.y0 + band.y1) / 2}
                dy="0.35em"
                textAnchor={onRight ? 'start' : 'end'}
                fontSize={11}
                fill="var(--text)"
                stroke="var(--bg)"
                strokeWidth={3}
                paintOrder="stroke"
              >
                {band.name}
                <tspan fillOpacity={0.6}> {formatCount(band.value)}</tspan>
              </text>
            );
          })}
        {data.dimensions.map((dim, i) => (
          <text
            key={dim.key}
            x={i * ((innerWidth - NODE_WIDTH) / (data.dimensions.length - 1)) + NODE_WIDTH / 2}
            y={-16}
            textAnchor={i === 0 ? 'start' : i === data.dimensions.length - 1 ? 'end' : 'middle'}
            fontSize={11}
            fontWeight={600}
            fill="var(--muted)"
          >
            {dim.label.toUpperCase()}
          </text>
        ))}
      </g>
    </svg>
  );
}
